{
  "justification": "Issue salience is dominated by the economy (46.8%) and accompanied by high concern about immigration and clear Euroscepticism, pointing to strong proportionality (merit and performance) and loyalty (national identity/sovereignty), with some authority emphasis via crime/terrorism. Care and equality appear but are less prioritized (NHS, class difference), sanctity signals are minor (environment, family values/morals), and the centrist tax–spend mean (5.05/10) tempers extremes.",
  "foundations": [
    {
      "foundation": "loyalty",
      "basis": "Immigration salience (18.6%), EU membership disapproval (50.1%), and mentions of asylum/national identity.",
      "weight": 0.28
    },
    {
      "foundation": "proportionality",
      "basis": "Economy general (46.8%) plus unemployment (3.7%), taxation/inflation, and welfare fraud (0.9%).",
      "weight": 0.24
    },
    {
      "foundation": "authority",
      "basis": "Crime (6.3%), terrorism (1.5%), and concern about dishonesty (1.4%).",
      "weight": 0.18
    },
    {
      "foundation": "care",
      "basis": "NHS (1.1%), environment (1.5%), unemployment (3.7%), education (0.8%), youth/pensions mentions.",
      "weight": 0.15
    },
    {
      "foundation": "equality",
      "basis": "Class difference (0.6%), housing (0.3%), and a centrist tax–spend position (mean 5.05/10).",
      "weight": 0.08
    },
    {
      "foundation": "sanctity",
      "basis": "Environment (1.5%), family values-lack (0.4%), morals (0.3%), failure of religious (0.1%).",
      "weight": 0.07
    }
  ]
}
